pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items == 0 { 1.0 } else { step_index as f64 / total_items as f64 };
    let mean = mean_residual.max(0.0);
    let residual = post_residual as f64;

    // Prefer a tight placement, especially when it can accommodate the
    // upcoming item.  A bin that becomes too tight is less reusable.
    score -= 0.85 * residual;
    score -= 0.65 * mean;
    score += 0.25 * (residual - mean);

    if next_item_size > 0 {
        if residual >= next_item_size as f64 {
            score -= 18.0;
        } else {
            score += 12.0 + 0.35 * (next_item_size as f64 - residual).max(0.0);
        }
    } else {
        score -= 10.0;
    }

    // Avoid creating fragmented dead space unless opening a fresh bin is
    // clearly preferable or this is the final fitting opportunity.
    if residual > 0.0 && residual < 10.0 {
        score += 7.0;
    }
    if residual < 20.0 && next_item_size > residual {
        score += 4.0;
    }

    // Strongly favor using an existing bin when only one can fit the item;
    // otherwise an aggressive new-bin policy may unnecessarily split load.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 14.0;
    }

    // A new empty bin has perfect future flexibility, but should only win
    // when the current item is poorly matched to all existing bins.
    if is_new_bin {
        score += 26.0;
        if fitting_bins_count == 0 {
            score -= 34.0;
        }
        if next_item_size > 0 && item_size < next_item_size {
            score -= 8.0;
        }
    }

    // Later in a long stream, preserve useful capacity for heterogeneous
    // arrivals rather than consuming a bin with a large current item.
    let horizon_weight = 0.5 + 0.5 * progress;
    if next_item_size > 0 {
        let size_gap = (next_item_size as f64 - item_size as f64).abs();
        score += horizon_weight * 0.08 * size_gap;
    }

    // Penalize choices that leave the bin substantially less capable than
    // the average open bin.
    if residual > mean {
        score += 0.30 * (residual - mean).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tiny gaps are usually unusable; treat them as strict dead space.
    let dead_space = if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        (item_size.min(next_item_size.max(1)) - post_residual) as f64
    } else {
        0.0
    };
    score += 18.0 * dead_space;

    // Also avoid leaving a residue below the likely range of future items.
    if post_residual > 0 && post_residual < 10 {
        score += 4.0 * (10.0 - post_residual as f64);
    }

    // Preserve useful capacity, while mildly rewarding a nearly tight fit.
    score += 0.35 * post_residual as f64;
    if post_residual == 0 {
        score -= 12.0;
    }

    // Opening another bin is more defensible when many bins are already open.
    let pressure = if open_bins_count == 0 {
        0.0
    } else {
        (open_bins_count as f64 / 4.0).min(8.0)
    };
    score += pressure;

    // A final available fitting bin is a scarce opportunity.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Near the end of the stream, reduce willingness to create dead space.
    let progress = if total_items == 0 {
        1.0
    } else {
        (step_index as f64 / total_items as f64).min(1.0)
    };
    score *= 1.0 + 0.25 * progress;

    // Favor placements close to the mean residual, which reduce imbalance.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * deviation;

    score
}
